PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS suppliers(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('buyer','owner','editor','analyst','admin')),supplier_id TEXT REFERENCES suppliers(id));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL REFERENCES suppliers(id),sku TEXT NOT NULL,data TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>0),stock INTEGER NOT NULL CHECK(stock>=0),published INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(supplier_id,sku));
CREATE TABLE IF NOT EXISTS invoices(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,user_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,request_hash TEXT NOT NULL,snapshot TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'awaiting_payment',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS invoice_pdfs(invoice_id TEXT NOT NULL REFERENCES invoices(id),version INTEGER NOT NULL,content BLOB NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(invoice_id,version));
CREATE TABLE IF NOT EXISTS order_lines(invoice_id TEXT NOT NULL REFERENCES invoices(id),supplier_id TEXT NOT NULL REFERENCES suppliers(id),product_id TEXT NOT NULL,name TEXT NOT NULL,sku TEXT NOT NULL,quantity INTEGER NOT NULL,unit_minor INTEGER NOT NULL,total_minor INTEGER NOT NULL,PRIMARY KEY(invoice_id,product_id));
CREATE TABLE IF NOT EXISTS imports(id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL REFERENCES suppliers(id),user_id TEXT NOT NULL REFERENCES users(id),file_name TEXT NOT NULL,payload TEXT NOT NULL,report TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL REFERENCES suppliers(id),name TEXT NOT NULL,email TEXT NOT NULL,note TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mail_log(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES invoices(id),recipient TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_supplier ON products(supplier_id);
CREATE INDEX IF NOT EXISTS idx_order_supplier ON order_lines(supplier_id);
